mapper.update:
UPDATE venues
SET visibility = #{visibility}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, name, description, address, city, location_lat, location_lng, metadata,
confidence, source, master_venue_id, created_by, visibility, created_at, updated_at
FROM venues
WHERE created_by = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE (
    created_by = #{userId}
    OR EXISTS (
        SELECT 1 FROM venue_shares
        WHERE venue_id = venues.id
        AND shared_with_user_id = #{userId}
    )
)

    AND (LOWER(name) LIKE LOWER(CONCAT('%', #{search}, '%'))
    OR LOWER(address) LIKE LOWER(CONCAT('%', #{search}, '%'))
    OR LOWER(city) LIKE LOWER(CONCAT('%', #{search}, '%')))


    AND LOWER(city) = LOWER(#{city})

mapper.select:
SELECT id, name, description, address, city, location_lat, location_lng, metadata,
       confidence, source, master_venue_id, created_by, visibility, created_at, updated_at
FROM venues
WHERE id = #{id}
AND (
    created_by = #{userId}
    OR EXISTS (
        SELECT 1 FROM venue_shares
        WHERE venue_id = #{id}
        AND shared_with_user_id = #{userId}
    )
)
